class AdversarialPassOneTests(BacklogTestCase):
    """Defects and weak oracles adversarial pass 1 found."""

    def write(self, name, records):
        write_jsonl(os.path.join(self.data, name), records)

    def test_completeness_needs_every_batch_number_not_just_the_count(self):
        # Regression: batches {0, 2} of 2 counted as 2 >= 2 although batch 1 never arrived.
        self.write("a.jsonl", [
            rec("h", "good", 1.0, [item("h", "r", "GOOD")]),
            rec("h", "gap", 2.0, [item("h", "r", "GAP-B0")], batch=0, batches=2),
            rec("h", "gap", 2.1, [item("h", "r", "GAP-B2")], batch=2, batches=2),
        ])
        err = io.StringIO()
        with contextlib.redirect_stderr(err):
            items, _s, newest = self.mod.pull()
        self.assertEqual(["GOOD"], [i["item_id"] for i in items])
        self.assertEqual({"h": (1.0, "good")}, newest)
        self.assertEqual("backlog: h: newest run gap is incomplete (1/2 batches) — kept the complete "
                         "run good\n", err.getvalue())

    def test_records_that_are_not_backlog_payloads_are_counted_on_stderr(self):
        # Regression: unparseable or host-less records were dropped with no word.
        self.write("a.jsonl", ["{not json", '"a bare string"', json.dumps({"payload": {"run_id": "x"}}),
                               "", rec("h", "r1", 1.0, [item("h", "r", "KEPT")])])
        err = io.StringIO()
        with contextlib.redirect_stderr(err):
            items, _s, _n = self.mod.pull()
        self.assertEqual(["KEPT"], [i["item_id"] for i in items])
        self.assertEqual("backlog: skipped 3 record(s) on the collector that are not backlog payloads "
                         "(unparseable JSON or no host)\n", err.getvalue())

    def test_failed_index_swap_keeps_the_previous_pair_and_removes_temp_files(self):
        self.write("a.jsonl", [rec("hostA", "r1", 1.0, [item("hostA", "repo", "NEW-1")])])
        self.seed_index('{"item_id": "OLD-1"}\n')
        with open(self.mod.META, "w") as f:
            json.dump({"hosts": {"old": {}}, "strays": [], "items": 1}, f)
        with mock.patch.object(self.mod.os, "replace", side_effect=OSError("cross-device")), \
                self.assertRaises(OSError):
            self.mod.pull()
        self.assertEqual(["OLD-1"], [i["item_id"] for i in self.index_items()])
        self.assertEqual({"hosts": {"old": {}}, "strays": [], "items": 1}, self.read_meta())
        self.assertEqual([], [n for n in os.listdir(self.zuvo) if n.endswith(".tmp")])


class AdversarialPassTwoTests(BacklogTestCase):
    """Fleet-supplied record shapes, the swap lock and the rollback's own failure (adversarial pass 2)."""

    def write(self, name, records):
        write_jsonl(os.path.join(self.data, name), records)

    def test_null_or_text_received_at_counts_as_zero_instead_of_crashing(self):
        # Regression: max(0, None) / max(0, "x") raised TypeError in the middle of the pull.
        def raw(ts, host, run, item_id):
            return {"received_at": ts, "payload": {"host": host, "run_id": run,
                                                   "items": [item(host, "r", item_id)]}}
        self.write("a.jsonl", [raw(None, "h", "r-null", "N"), raw("yesterday", "g", "r-str", "S"),
                               raw(1.0, "h", "r-num", "NUM")])
        items, _s, newest = self.mod.pull()
        self.assertEqual({"h": (1.0, "r-num"), "g": (0, "r-str")}, newest)
        self.assertEqual(["NUM", "S"], sorted(i["item_id"] for i in items))

    def test_a_batch_delivered_twice_is_counted_once(self):
        # Regression: a retried POST of batch 0 doubled its items in the index.
        self.write("a.jsonl", [
            rec("h", "r1", 1.0, [item("h", "r", "B0-ITEM")], batch=0, batches=2),
            rec("h", "r1", 1.5, [item("h", "r", "B0-ITEM")], batch=0, batches=2),
            rec("h", "r1", 2.0, [item("h", "r", "B1-ITEM")], batch=1, batches=2),
        ])
        err = io.StringIO()
        with contextlib.redirect_stderr(err):
            items, _s, newest = self.mod.pull()
        self.assertEqual(["B0-ITEM", "B1-ITEM"], [i["item_id"] for i in items])
        self.assertEqual({"h": (2.0, "r1")}, newest)
        self.assertEqual("", err.getvalue())

    def test_items_that_are_not_objects_are_dropped(self):
        self.write("a.jsonl", [{"received_at": 1.0, "payload": {
            "host": "h", "run_id": "r1", "items": ["a string", 7, None, item("h", "r", "OBJ")]}}])
        items, _s, _n = self.mod.pull()
        self.assertEqual(["OBJ"], [i["item_id"] for i in items])

    def test_a_failed_rollback_names_both_failures(self):
        self.write("a.jsonl", [rec("hostA", "r1", 1.0, [item("hostA", "repo", "NEW-1")])])
        self.seed_index('{"item_id": "OLD-1"}\n')
        real_replace = os.replace

        def replace(src, dst):
            if dst == self.mod.META:
                raise OSError("meta swap failed")
            if src.endswith(".prev"):
                raise OSError("rollback failed")
            return real_replace(src, dst)
        with mock.patch.object(self.mod.os, "replace", side_effect=replace), \
                self.assertRaises(OSError) as cm:
            self.mod.pull()
        self.assertEqual(f"meta swap failed; rolling the index back also failed (rollback failed) — "
                         f"{self.mod.INDEX} is newer than {self.mod.META}", str(cm.exception))

    def test_the_write_and_swap_run_under_an_exclusive_lock(self):
        self.write("a.jsonl", [rec("hostA", "r1", 1.0, [item("hostA", "repo", "NEW-1")])])
        calls = []
        fake_fcntl = mock.Mock(LOCK_EX=2)
        fake_fcntl.flock.side_effect = lambda fh, op: calls.append(
            (fh.name, op, os.path.exists(self.mod.INDEX)))
        with mock.patch.dict(sys.modules, {"fcntl": fake_fcntl}):
            self.mod.pull()
        self.assertEqual([(self.mod.INDEX + ".lock", 2, False)], calls)
        self.assertEqual(["NEW-1"], [i["item_id"] for i in self.index_items()])

    def test_without_fcntl_the_pull_still_writes(self):
        self.write("a.jsonl", [rec("hostA", "r1", 1.0, [item("hostA", "repo", "NEW-1")])])
        with mock.patch.dict(sys.modules, {"fcntl": None}):
            self.mod.pull()
        self.assertEqual(["NEW-1"], [i["item_id"] for i in self.index_items()])

    def test_text_mode_output_that_is_not_utf8_still_reaches_the_message(self):
        # Regression: text mode decoded strictly, so a non-UTF-8 byte raised out of subprocess.
        msg, _o, _e = self.exit_message(self.mod.collector_ssh, "printf 'bad \\377 byte\\n' >&2; exit 3",
                                        5, "probe")
        self.assertIn("(exit 3: bad \ufffd byte)", msg)

    def test_conf_inline_comment_and_unquoted_export_are_read(self):
        zhome = os.path.join(self.tmp, "zhome")
        os.makedirs(zhome)
        os.environ.pop("ZUVO_COLLECTOR_SSH", None)
        os.environ["ZUVO_HOME"] = zhome
        conf = os.path.join(zhome, "collector.conf")
        for text, want in (("ZUVO_COLLECTOR_SSH=box-1  # the collector\n", "box-1"),
                           ("export ZUVO_COLLECTOR_SSH=plain-host\n", "plain-host")):
            with self.subTest(text=text):
                with open(conf, "w", encoding="utf-8") as f:
                    f.write(text)
                self.assertEqual(want, self.mod._collector_host())


class ReauditEdgeTests(BacklogTestCase):
    """Edges the third blind re-audit named (codex-5.3)."""

    def write(self, name, records):
        write_jsonl(os.path.join(self.data, name), records)

    def test_boolean_received_at_counts_as_zero_not_as_one(self):
        # bool is an int subclass: True would otherwise read as timestamp 1 and beat a real 0.5.
        def raw(ts, run, item_id):
            return {"received_at": ts,
                    "payload": {"host": "h", "run_id": run, "items": [item("h", "r", item_id)]}}
        self.write("a.jsonl", [raw(True, "r-bool", "BOOL"), raw(0.5, "r-real", "REAL")])
        items, _s, newest = self.mod.pull()
        self.assertEqual({"h": (0.5, "r-real")}, newest)
        self.assertEqual(["REAL"], [i["item_id"] for i in items])

    def test_the_last_batch_carrying_strays_decides_them(self):
        self.write("a.jsonl", [
            rec("h", "r1", 1.0, [item("h", "r", "B0")], strays=["/first"], batch=0, batches=2),
            rec("h", "r1", 1.1, [item("h", "r", "B1")], strays=["/second"], batch=1, batches=2),
        ])
        _i, strays, _n = self.mod.pull()
        self.assertEqual([{"host": "h", "path": "/second"}], strays)

    def test_of_several_incomplete_runs_the_newest_is_used(self):
        self.write("a.jsonl", [
            rec("h", "older-partial", 1.0, [item("h", "r", "OLD")], batch=0, batches=2),
            rec("h", "newer-partial", 2.0, [item("h", "r", "NEW")], batch=0, batches=3),
        ])
        err = io.StringIO()
        with contextlib.redirect_stderr(err):
            items, _s, newest = self.mod.pull()
        self.assertEqual({"h": (2.0, "newer-partial")}, newest)
        self.assertEqual(["NEW"], [i["item_id"] for i in items])
        self.assertEqual("backlog: h: run newer-partial is incomplete (1/3 batches) and no complete run "
                         "exists — using it; that host's items are short\n", err.getvalue())

    def test_a_second_pull_waits_for_the_lock_held_by_another_process(self):
        if "fcntl" not in sys.modules:
            try:
                import fcntl  # noqa: F401
            except ImportError:
                self.skipTest("no fcntl on this platform: the swap is not locked")
        self.write("a.jsonl", [rec("hostA", "r1", 1.0, [item("hostA", "repo", "NEW-1")])])
        os.makedirs(self.zuvo, exist_ok=True)
        # The holder keeps the lock until told to let go — no sleep, no elapsed-time threshold. While it
        # holds it, pull must still be blocked; a pull that ignored the lock would already be done.
        holder = subprocess.Popen(
            [sys.executable, "-c",
             "import fcntl, sys\n"
             "f = open(sys.argv[1], 'a'); fcntl.flock(f, fcntl.LOCK_EX)\n"
             "print('locked', flush=True); sys.stdin.readline()\n",
             self.mod.INDEX + ".lock"], stdin=subprocess.PIPE, stdout=subprocess.PIPE, text=True)
        self.addCleanup(holder.wait)
        # Cleanups run last-in first-out: the holder is released (stdin closed -> readline returns)
        # BEFORE it is waited for, so a failing assertion below cannot leave the wait hanging forever.
        self.addCleanup(lambda: holder.stdin.closed or holder.stdin.close())
        self.assertEqual("locked\n", holder.stdout.readline())
        holder.stdout.close()
        errors = []

        def run_pull():
            try:
                self.mod.pull()
            except BaseException as e:   # surfaced below, not swallowed
                errors.append(e)
        worker = threading.Thread(target=run_pull, daemon=True)   # daemon: never outlives a failed test
        worker.start()
        worker.join(timeout=1.0)
        self.assertTrue(worker.is_alive(), "pull finished while another process held the index lock")
        self.assertFalse(os.path.exists(self.mod.INDEX))
        holder.stdin.write("release\n")
        holder.stdin.close()
        worker.join(timeout=30)
        self.assertFalse(worker.is_alive())
        self.assertEqual([], errors)
        self.assertEqual(["NEW-1"], [i["item_id"] for i in self.index_items()])
        self.assertEqual(1, self.read_meta()["items"])
        self.assertEqual([], [n for n in os.listdir(self.zuvo) if n.endswith((".tmp", ".prev"))])


class FinalReviewTests(BacklogTestCase):
    """The final full-content cross-model review: fleet field types and the lock's own failure."""

    def write(self, name, records):
        write_jsonl(os.path.join(self.data, name), records)

    def payload(self, run, ts, item_id, **extra):
        p = {"host": "h", "run_id": run, "items": [item("h", "r", item_id)]}
        p.update(extra)
        return {"received_at": ts, "payload": p}

    def test_a_boolean_batch_is_not_batch_one(self):
        # bool is an int subclass: True used to count as batch 1, completing a 2-batch run.
        self.write("a.jsonl", [rec("h", "good", 1.0, [item("h", "r", "GOOD")]),
                               self.payload("bool", 2.0, "B0", batch=0, batches=2),
                               self.payload("bool", 2.1, "BT", batch=True, batches=2)])
        err = io.StringIO()
        with contextlib.redirect_stderr(err):
            _i, _s, newest = self.mod.pull()
        self.assertEqual({"h": (1.0, "good")}, newest)
        self.assertIn("newest run bool is incomplete (1/2 batches)", err.getvalue())

    def test_a_huge_declared_batch_count_is_counted_not_materialised(self):
        # range(10**12) used to be built as a set; now the run is simply incomplete, instantly.
        self.write("a.jsonl", [rec("h", "good", 1.0, [item("h", "r", "GOOD")]),
                               self.payload("huge", 2.0, "H0", batch=0, batches=10 ** 12)])
        err = io.StringIO()
        with contextlib.redirect_stderr(err):
            _i, _s, newest = self.mod.pull()
        self.assertEqual({"h": (1.0, "good")}, newest)
        self.assertIn(f"newest run huge is incomplete (1/{10 ** 12} batches)", err.getvalue())

    def test_zero_or_negative_batches_declare_nothing(self):
        for declared in (0, -2, True, "2"):
            with self.subTest(batches=declared):
                self.write("a.jsonl", [rec("h", "old", 1.0, [item("h", "r", "OLD")]),
                                       self.payload("new", 2.0, "NEW", batch=0, batches=declared)])
                items, _s, newest = self.mod.pull()
                self.assertEqual({"h": (2.0, "new")}, newest)
                self.assertEqual(["NEW"], [i["item_id"] for i in items])

    def test_a_line_separator_inside_a_json_string_does_not_split_the_record(self):
        # Written raw (ensure_ascii off): str.splitlines() broke the record at U+2028.
        rec_line = json.dumps(rec("h", "r1", 1.0, [item("h", "r", "LS", text="a\u2028b")]),
                              ensure_ascii=False)
        self.write("a.jsonl", [rec_line])
        err = io.StringIO()
        with contextlib.redirect_stderr(err):
            items, _s, _n = self.mod.pull()
        self.assertEqual(["a\u2028b"], [i["text"] for i in items])
        self.assertEqual("", err.getvalue())

    def test_strays_keep_only_path_strings(self):
        self.write("a.jsonl", [self.payload("r1", 1.0, "X",
                                            stray_worktree_copies=["/ok", 7, None, {"p": 1}])])
        _i, strays, _n = self.mod.pull()
        self.assertEqual([{"host": "h", "path": "/ok"}], strays)
        self.write("a.jsonl", [self.payload("r2", 2.0, "Y", stray_worktree_copies="/not/a/list")])
        _i, strays, _n = self.mod.pull()
        self.assertEqual([], strays)

    def test_a_flock_that_raises_still_closes_the_lock_and_writes_nothing(self):
        self.write("a.jsonl", [rec("hostA", "r1", 1.0, [item("hostA", "repo", "NEW-1")])])
        before = self.seed_index()
        opened = []
        real_open = open

        def tracking_open(path, *a, **kw):
            fh = real_open(path, *a, **kw)
            if str(path).endswith(".lock"):
                opened.append(fh)
            return fh
        fake_fcntl = mock.Mock(LOCK_EX=2)
        fake_fcntl.flock.side_effect = OSError("no locks available")
        with mock.patch.dict(sys.modules, {"fcntl": fake_fcntl}), \
                mock.patch("builtins.open", side_effect=tracking_open), self.assertRaises(OSError):
            self.mod.pull()
        self.assertEqual(1, len(opened))
        self.assertTrue(opened[0].closed)
        self.assertEqual(before, self.read_index())


